use super::cholesky::sample_multivariate_normal;
use super::gaussian_process::GaussianProcess;
use super::hypervolume::hypervolume_improvement_from_samples;
use super::hypervolume_samples::HypervolumeSamples;
use super::normal::normal_cdf;
use super::normal::normal_pdf;
use ndarray::Array1;

pub(super) fn expected_improvement(best: f64, mean: f64, std: f64, xi: f64) -> f64 {
    if std <= 1e-12 {
        return 0.0;
    }
    let improvement = best - mean - xi.max(0.0);
    let z = improvement / std;
    improvement * normal_cdf(z) + std * normal_pdf(z)
}

pub(super) fn expected_hypervolume_improvement_mc(
    gps: &[GaussianProcess],
    batch_norm: &[Array1<f64>],
    reference: &[f64],
    hv_samples: &HypervolumeSamples,
    normals: &[Vec<Vec<f64>>],
) -> f64 {
    if gps.is_empty() || batch_norm.is_empty() || normals.is_empty() {
        return 0.0;
    }

    let joint = gps
        .iter()
        .map(|gp| gp.predict_joint(batch_norm))
        .collect::<Vec<_>>();
    let mut total = 0.0;
    for draw in normals {
        let mut sampled_points = vec![vec![0.0; gps.len()]; batch_norm.len()];
        for (objective, (means, cov)) in joint.iter().enumerate() {
            let sample = sample_multivariate_normal(means, cov, &draw[objective]);
            for i in 0..batch_norm.len() {
                sampled_points[i][objective] = sample[i];
            }
        }
        total += hypervolume_improvement_from_samples(&sampled_points, reference, hv_samples);
    }
    total / normals.len() as f64
}
